package com.earthtrip.notification.adapter.out.persistence.notification;import com.earthtrip.notification.application.port.out.NotificationStorePort;import com.fasterxml.jackson.core.*;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.springframework.stereotype.Component;
@Component class NotificationPersistenceAdapter implements NotificationStorePort{private static final TypeReference<Map<String,Object>>MAP=new TypeReference<>(){};private final NotificationJpaRepository notifications;private final NotificationPreferenceJpaRepository preferences;private final PushDeviceJpaRepository devices;private final ObjectMapper json;NotificationPersistenceAdapter(NotificationJpaRepository n,NotificationPreferenceJpaRepository p,PushDeviceJpaRepository d,ObjectMapper j){notifications=n;preferences=p;devices=d;json=j;}@Override public List<NotificationRecord>list(UUID user){return notifications.findAllByUserIdAndHiddenAtIsNullOrderByCreatedAtDesc(user.toString()).stream().map(this::record).toList();}@Override public Optional<NotificationRecord>find(UUID id){return notifications.findById(id.toString()).map(this::record);}@Override public NotificationRecord save(NotificationRecord r){String data=write(r.metadata());NotificationJpaEntity e=notifications.findById(r.id().toString()).orElseGet(NotificationJpaEntity::new);e.apply(r,data);return record(notifications.saveAndFlush(e));}@Override public Optional<PreferenceRecord>preference(UUID user){return preferences.findById(user.toString()).map(NotificationPreferenceJpaEntity::record);}@Override public PreferenceRecord savePreference(PreferenceRecord r){NotificationPreferenceJpaEntity e=preferences.findById(r.userId().toString()).orElseGet(NotificationPreferenceJpaEntity::new);e.apply(r);return preferences.saveAndFlush(e).record();}@Override public void saveDevice(DeviceRecord r){PushDeviceJpaEntity e=devices.findById(r.deviceId()).orElseGet(PushDeviceJpaEntity::new);e.apply(r);devices.save(e);}@Override public Optional<DeviceRecord>device(String id){return devices.findById(id).map(PushDeviceJpaEntity::record);}private NotificationRecord record(NotificationJpaEntity e){try{return e.record(json.readValue(e.metadata(),MAP));}catch(JsonProcessingException x){throw new IllegalStateException("알림 메타데이터를 읽을 수 없습니다.",x);}}private String write(Object o){try{return json.writeValueAsString(o);}catch(JsonProcessingException x){throw new IllegalArgumentException("알림 메타데이터를 저장할 수 없습니다.",x);}}}
